<?php $q=mysqli_query($koneksi,"SELECT k.*,COUNT(a.idalat) jumlah FROM kategori k LEFT JOIN alat a ON a.idkategori=k.idkategori GROUP BY k.idkategori ORDER BY k.namakategori");
function fotoBawaanKategori($nama){$n=strtolower($nama);if(strpos($n,'elektronik')!==false||strpos($n,'komputer')!==false)return 'cat_elektronik.jpg';if(strpos($n,'aksesori')!==false||strpos($n,'aksesoris')!==false||strpos($n,'kabel')!==false)return 'cat_aksesoris.jpg';return 'cat_peralatan.jpg';}
?>
<section class="page-public"><div class="container"><div class="public-page-heading"><div><span class="eyebrow">KOLEKSI</span><h1>Kategori Sarana</h1><p>Temukan sarana berdasarkan kelompok peralatan.</p></div></div><div class="row"><?php while($r=mysqli_fetch_assoc($q)): ?><div class="col-md-6 col-lg-4 mb-4"><a class="category-card" href="index.php?halaman=detailkategori&id=<?=$r['idkategori']?>"><div class="category-icon"><?php $fotoKategori=(!empty($r['foto']) && file_exists(__DIR__.'/../../assets/uploads/kategori/'.$r['foto']))?$r['foto']:fotoBawaanKategori($r['namakategori']); ?><img src="assets/uploads/kategori/<?=htmlspecialchars($fotoKategori)?>" alt="Gambar <?=htmlspecialchars($r['namakategori'])?>" style="width:100%;height:100%;object-fit:cover;border-radius:12px"></div><div><span>Kategori</span><h3><?=htmlspecialchars($r['namakategori'])?></h3><p><?=$r['jumlah']?> sarana tersedia</p></div><i class="fas fa-arrow-right category-arrow"></i></a></div><?php endwhile; ?></div></div></section>